CREATE POLICY "posts_images_read" ON storage.objects FOR SELECT USING (bucket_id = 'posts');
CREATE POLICY "posts_images_insert_own" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'posts' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "posts_images_update_own" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'posts' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "posts_images_delete_own" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'posts' AND (storage.foldername(name))[1] = auth.uid()::text);